// Aggregate data from all three sheets for P&L calculation
// This node runs after all three reads are complete
const allItems = $input.all();

// Get week boundaries (Monday to Friday)
const now = new Date();
const dayOfWeek = now.getDay();
const monday = new Date(now);
monday.setDate(now.getDate() - (dayOfWeek === 0 ? 6 : dayOfWeek - 1));
monday.setHours(0, 0, 0, 0);
const friday = new Date(now);
friday.setHours(23, 59, 59, 999);

// We pass the week boundaries for Claude context
return [{
  json: {
    week_start: monday.toISOString().split('T')[0],
    week_end: friday.toISOString().split('T')[0],
    report_generated: now.toISOString(),
    business_name: process.env.BUSINESS_NAME || '{{$env.BUSINESS_NAME}}'
  }
}];

// Parse Claude's JSON response
const claudeOutput = $input.item.json.content || $input.item.json.text || $input.item.json.output || '';
let report;
try {
  const jsonMatch = claudeOutput.match(/\{[\s\S]*\}/);
  report = jsonMatch ? JSON.parse(jsonMatch[0]) : { whatsapp_summary: claudeOutput, week_start: new Date().toISOString().split('T')[0] };
} catch(e) {
  report = { whatsapp_summary: claudeOutput, week_start: new Date().toISOString().split('T')[0], parse_error: e.message };
}
return { json: report };
